def longest_two_fruit_window(fruits):
 counts={};left=best=0
 for right,value in enumerate(fruits):
  counts[value]=counts.get(value,0)+1
  while len(counts)>2:
   old=fruits[left];counts[old]-=1;left+=1
   if counts[old]==0:del counts[old]
  best=max(best,right-left+1)
 return best

